from collections import defaultdict
from typing import Any, Optional


class DataProcessor:
    def filter(self, data: list[dict], field: str, value: Any) -> list[dict]:
        return [item for item in data if item.get(field) == value]

    def sort(self, data: list[dict], key: Optional[str] = None, reverse: bool = False) -> list[dict]:
        return sorted(data, key=lambda x: x.get(key), reverse=reverse)

    def group(self, data: list[dict], field: Optional[str] = None) -> dict:
        groups = defaultdict(list)
        for item in data:
            groups[item.get(field)].append(item)
        return dict(groups)

    def aggregate(self, data: list[dict], field: Optional[str] = None, func: str = 'sum') -> Any:
        values = [item.get(field, 0) for item in data]
        aggregators = {
            'sum': lambda v: sum(v),
            'avg': lambda v: sum(v) / len(v) if v else 0,
            'min': lambda v: min(v) if v else None,
            'max': lambda v: max(v) if v else None,
        }
        if func not in aggregators:
            raise ValueError(f'Unknown aggregate function: {func}')
        return aggregators[func](values)
